jumlah_pesanan = 0
total = 0
terbesar = 0
while True:
    boks = int(input())
    if boks == 0:
        break
    if boks < 0:
        print("Jumlah tidak valid, dilewati")
    jumlah_pesanan += 1
    total += boks
    if boks > terbesar:
        terbesar = boks
if jumlah_pesanan == 0:
    print("Tidak ada pesanan")
else:
    print(f"Jumlah pesanan: {jumlah_pesanan}")
    print(f"Total boks: {total}")
    print(f"Rata-rata: {total / jumlah_pesanan:.2f}")
    print(f"Terbesar: {terbesar}")
